import json
import re

def parse_value(val):
    if not val:
        return val
    parts = val.split()
    if len(parts) >= 4:
        month_str = parts[1]
        day_str = parts[2].rstrip(',')
        year_str = parts[3]
        months = {
            'Jan.': '01', 'Feb.': '02', 'March': '03', 'April': '04',
            'May': '05', 'June': '06', 'July': '07', 'Aug.': '08',
            'Sept.': '09', 'Oct.': '10', 'Nov.': '11', 'Dec.': '12'
        }
        if month_str in months and day_str.isdigit() and year_str.isdigit():
            return f"{year_str}-{months[month_str]}-{int(day_str):02d}"
    return val

def parse_html(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    articles = re.findall(r'<article class="sheet".*?</article>', content, re.DOTALL)

    records = []
    for article in articles:
        rows = re.findall(r'<tr.*?>(.*?)</tr>', article, re.DOTALL)
        record = {}
        for row in rows:
            th_match = re.search(r'<th.*?>(.*?)</th>', row, re.DOTALL)
            td_match = re.search(r'<td.*?>(.*?)</td>', row, re.DOTALL)
            if th_match and td_match:
                key = re.sub(r'<[^>]+>', '', th_match.group(1)).strip()
                td_content = td_match.group(1)
                if 'class="void"' in td_match.group(0):
                    val = None
                else:
                    val = re.sub(r'<[^>]+>', '', td_content).strip()
                record[key] = val
        records.append(record)
    return records

def resolve_fact(entity, sources, db):
    for doc_name, field_name in sources:
        if doc_name in db and entity in db[doc_name]:
            record = db[doc_name][entity]
            if field_name in record:
                values = record[field_name]
                if len(values) == 1:
                    return [list(values)[0], doc_name]
                elif len(values) > 1:
                    return "CONFLICT"
    return "ABSENT"

