import sys
import os
import json
import re
from datetime import date, timedelta

def extract_tuples(values_str):
    tuples = []
    in_string = False
    current_tuple = []
    current_val = []
    in_tuple = False

    i = 0
    while i < len(values_str):
        c = values_str[i]
        if c == "'":
            in_string = not in_string
            current_val.append(c)
        elif not in_string:
            if c == '(':
                in_tuple = True
                current_val = []
                current_tuple = []
            elif c == ')':
                if in_tuple:
                    current_tuple.append(''.join(current_val))
                    tuples.append(current_tuple)
                    current_tuple = []
                    current_val = []
                    in_tuple = False
            elif c == ',':
                if in_tuple:
                    current_tuple.append(''.join(current_val))
                    current_val = []
            else:
                current_val.append(c)
        else:
            current_val.append(c)
        i += 1

    cleaned_tuples = []
    for t in tuples:
        cleaned = []
        for v in t:
            v = v.strip()
            if v.upper() == 'NULL':
                cleaned.append(None)
            elif v.startswith("'") and v.endswith("'"):
                val = v[1:-1].replace("''", "'")
                cleaned.append(val)
            else:
                try:
                    cleaned.append(int(v))
                except ValueError:
                    try:
                        cleaned.append(float(v))
                    except ValueError:
                        cleaned.append(v)
        cleaned_tuples.append(cleaned)
    return cleaned_tuples

def parse_sql_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    records = []
    inserts = re.finditer(r"INSERT INTO\s+(\w+)\s*\(([^)]+)\)\s*VALUES\s*(.*?);", content, re.DOTALL | re.IGNORECASE)
    for insert in inserts:
        cols = [c.strip() for c in insert.group(2).split(',')]
        values_str = insert.group(3)
        tuples = extract_tuples(values_str)
        for t in tuples:
            if len(t) == len(cols):
                records.append(dict(zip(cols, t)))
    return records

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    data_dir = sys.argv[1]

    doc_files = {
        "dol_receipts": "dol_receipts.sql",
        "ead_cards": "ead_cards.sql",
        "hr_roster": "hr_roster.sql",
        "lca_filings": "lca_filings.sql",
        "lca_notices": "lca_notices.sql",
        "reverifications": "reverifications.sql",
        "work_authorizations": "work_authorizations.sql"
    }

    db = {}
    for doc_name, filename in doc_files.items():
        filepath = os.path.join(data_dir, filename)
        if os.path.exists(filepath):
            db[doc_name] = parse_sql_file(filepath)
        else:
            db[doc_name] = []

    def get_fact(doc_name, wkr_code, col_name):
        if doc_name not in db:
            return "ABSENT"

        values = set()
        for row in db[doc_name]:
            if row.get('wkr_code') == wkr_code:
                val = row.get(col_name)
                if val is not None:
                    values.add(val)

        if len(values) == 0:
            return "ABSENT"
        elif len(values) > 1:
            return "CONFLICT"
        else:
            val = values.pop()
            if col_name.endswith('_epd') and isinstance(val, int):
                val = (date(1970, 1, 1) + timedelta(days=val)).strftime('%Y-%m-%d')
            elif col_name.endswith('_cents') and isinstance(val, int):
                val = f"{val / 100:.2f}"
            else:
                val = str(val)
            return [val, doc_name]

    def resolve_fact(wkr_code, primary_doc, primary_col, fallback_doc=None, fallback_col=None):
        res = get_fact(primary_doc, wkr_code, primary_col)
        if res == "CONFLICT":
            return "CONFLICT"
        if res != "ABSENT":
            return res

        if fallback_doc:
            res_fallback = get_fact(fallback_doc, wkr_code, fallback_col)
            return res_fallback

        return "ABSENT"

    wkr_codes = set()
    for doc_name, rows in db.items():
        for row in rows:
            if 'wkr_code' in row:
                wkr_codes.add(row['wkr_code'])
    wkr_codes = sorted(list(wkr_codes))

    output = {}
    for wkr in wkr_codes:
        # wf.reverify_window
        pair_id = f"wf.reverify_window::{wkr}"
        output[pair_id] = {
            "authorization expiry": resolve_fact(wkr, "work_authorizations", "eligibility_doc_lapse_epd", "ead_cards", "ead_lapse_epd"),
            "reverification date": resolve_fact(wkr, "reverifications", "i9_redo_done_epd")
        }

        # wf.notice_posting
        pair_id = f"wf.notice_posting::{wkr}"
        output[pair_id] = {
            "notice posted": resolve_fact(wkr, "lca_notices", "board_pinned_epd"),
            "notice removed": resolve_fact(wkr, "lca_notices", "board_unpinned_epd"),
            "LCA filed": resolve_fact(wkr, "lca_filings", "lca_lodge_epd", "dol_receipts", "agency_stamp_epd")
        }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
