import sys
import os
import re
import json
import datetime
from collections import defaultdict

def epd_to_date(epd):
    if epd is None:
        return None
    return (datetime.date(1970, 1, 1) + datetime.timedelta(days=int(epd))).strftime('%Y-%m-%d')

def parse_sql_values(values_str):
    tuples = []
    in_string = False
    current_tuple = []
    current_val = []
    in_tuple = False

    for char in values_str:
        if char == "'" and not in_string:
            in_string = True
            current_val.append(char)
        elif char == "'" and in_string:
            in_string = False
            current_val.append(char)
        elif char == '(' and not in_string:
            in_tuple = True
            current_val = []
            current_tuple = []
        elif char == ')' and not in_string:
            if in_tuple:
                current_tuple.append(''.join(current_val).strip())
                tuples.append(current_tuple)
                in_tuple = False
        elif char == ',' and not in_string and in_tuple:
            current_tuple.append(''.join(current_val).strip())
            current_val = []
        elif in_tuple:
            current_val.append(char)

    cleaned_tuples = []
    for t in tuples:
        cleaned = []
        for v in t:
            if v.startswith("'") and v.endswith("'"):
                cleaned.append(v[1:-1])
            elif v.upper() == 'NULL':
                cleaned.append(None)
            else:
                cleaned.append(v)
        cleaned_tuples.append(cleaned)

    return cleaned_tuples

def parse_sql_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    inserts = re.findall(r'INSERT INTO\s+\w+\s*\(([^)]+)\)\s*VALUES\s*(.*?);', content, re.DOTALL | re.IGNORECASE)

    records = defaultdict(list)
    for cols_str, values_str in inserts:
        cols = [c.strip() for c in cols_str.split(',')]

        tuples = parse_sql_values(values_str)
        for t in tuples:
            if len(t) != len(cols):
                continue
            row = dict(zip(cols, t))
            if 'wkr_code' in row:
                records[row['wkr_code']].append(row)
    return records

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    data = {}
    for filename in os.listdir(dir_path):
        if filename.endswith('.sql'):
            filepath = os.path.join(dir_path, filename)
            data[filename] = parse_sql_file(filepath)

    RULES = {
        "wf.reverify_window": {
            "authorization expiry": [
                ("work_authorizations.sql", "eligibility_doc_lapse_epd", "date"),
                ("ead_cards.sql", "ead_lapse_epd", "date")
            ],
            "reverification date": [
                ("reverifications.sql", "i9_redo_done_epd", "date")
            ]
        },
        "wf.notice_posting": {
            "notice posted": [
                ("lca_notices.sql", "board_pinned_epd", "date")
            ],
            "notice removed": [
                ("lca_notices.sql", "board_unpinned_epd", "date")
            ],
            "LCA filed": [
                ("lca_filings.sql", "lca_lodge_epd", "date"),
                ("dol_receipts.sql", "agency_stamp_epd", "date")
            ]
        }
    }

    entities = set()
    for doc_data in data.values():
        entities.update(doc_data.keys())

    pairs = []
    for rule in RULES.keys():
        for entity in sorted(entities):
            pairs.append(f"{rule}::{entity}")

    output = {}

    for pair in pairs:
        rule_name, entity = pair.split("::")
        if rule_name not in RULES:
            continue

        rule_facts = RULES[rule_name]
        pair_output = {}

        for fact_name, sources in rule_facts.items():
            fact_val = "ABSENT"

            for doc_file, col, typ in sources:
                if doc_file not in data:
                    continue
                if entity not in data[doc_file]:
                    continue

                vals = set()
                for row in data[doc_file][entity]:
                    val = row.get(col)
                    if val is not None:
                        vals.add(val)

                if len(vals) > 1:
                    fact_val = "CONFLICT"
                    break
                elif len(vals) == 1:
                    val = vals.pop()
                    if typ == "date":
                        val = epd_to_date(val)
                    doc_name = doc_file.replace('.sql', '')
                    fact_val = [val, doc_name]
                    break

            pair_output[fact_name] = fact_val

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
