import sys
import os
import json
import collections

def parse_edi(filepath, segment_prefixes):
    data = collections.defaultdict(lambda: collections.defaultdict(set))
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    segments = content.split('~')
    current_entity = None
    current_facts = collections.defaultdict(set)

    for segment in segments:
        segment = segment.strip()
        if not segment:
            continue
        parts = segment.split('*')
        if parts[0] == 'LX':
            if current_entity:
                for k, v in current_facts.items():
                    for val in v:
                        data[current_entity][k].add(val)
            current_entity = None
            current_facts = collections.defaultdict(set)
        elif parts[0] == 'REF' and len(parts) >= 3 and parts[1] == 'EI':
            current_entity = parts[2]
        else:
            for prefix, fact_name in segment_prefixes.items():
                if segment.startswith(prefix + '*'):
                    remainder = segment[len(prefix)+1:]
                    value = remainder.split('*')[0].strip()
                    # Format dates as YYYY-MM-DD
                    if len(value) == 8 and value.isdigit():
                        value = f"{value[:4]}-{value[4:6]}-{value[6:]}"
                    current_facts[fact_name].add(value)

    if current_entity:
        for k, v in current_facts.items():
            for val in v:
                data[current_entity][k].add(val)

    return data

def main():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]

    file_fact_mappings = {
        "work_authorizations": {"DTP*036*D8": "authorization expiry"},
        "ead_cards": {"DTP*438*D8": "authorization expiry"},
        "reverifications": {"DTP*572*D8": "reverification date"},
        "lca_notices": {"DTP*196*D8": "notice posted", "DTP*197*D8": "notice removed"},
        "lca_filings": {"DTP*640*D8": "LCA filed"},
        "dol_receipts": {"DTP*009*D8": "LCA filed"}
    }

    parsed_docs = {}
    for doc_name, mappings in file_fact_mappings.items():
        filepath = os.path.join(dir_path, doc_name + ".edi")
        if os.path.exists(filepath):
            parsed_docs[doc_name] = parse_edi(filepath, mappings)
        else:
            parsed_docs[doc_name] = {}

    rules = {
        "wf.reverify_window": {
            "authorization expiry": ["work_authorizations", "ead_cards"],
            "reverification date": ["reverifications"]
        },
        "wf.notice_posting": {
            "notice posted": ["lca_notices"],
            "notice removed": ["lca_notices"],
            "LCA filed": ["lca_filings", "dol_receipts"]
        }
    }

    # Extract all unique entities from all .edi files to dynamically generate pairs
    all_entities = set()
    if os.path.isdir(dir_path):
        for filename in os.listdir(dir_path):
            if filename.endswith('.edi'):
                filepath = os.path.join(dir_path, filename)
                with open(filepath, 'r', encoding='utf-8') as f:
                    content = f.read()
                for segment in content.split('~'):
                    parts = segment.strip().split('*')
                    if len(parts) >= 3 and parts[0] == 'REF' and parts[1] == 'EI':
                        all_entities.add(parts[2])

    pairs = []
    for rule_id in ["wf.reverify_window", "wf.notice_posting"]:
        for entity in sorted(all_entities):
            pairs.append(f"{rule_id}::{entity}")

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::")
        rule_facts = rules[rule_id]

        pair_output = {}
        for fact_name, doc_chain in rule_facts.items():
            resolved = "ABSENT"
            for doc_name in doc_chain:
                doc_data = parsed_docs.get(doc_name, {})
                if entity in doc_data and fact_name in doc_data[entity]:
                    values = doc_data[entity][fact_name]
                    if len(values) > 1:
                        resolved = "CONFLICT"
                        break
                    elif len(values) == 1:
                        resolved = [list(values)[0], doc_name]
                        break
            pair_output[fact_name] = resolved

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
