import sys
import os
import json
import collections

def extract_facts_from_file(filepath, field_prefixes):
    results = {prefix: collections.defaultdict(set) for prefix in field_prefixes}
    try:
        with open(filepath, 'r') as f:
            content = f.read()
    except FileNotFoundError:
        return results

    segments = content.split('~')

    loops = []
    current_loop = collections.defaultdict(list)
    for segment in segments:
        segment = segment.strip()
        if not segment:
            continue
        parts = segment.split('*')
        if parts[0] == 'LX':
            if current_loop:
                loops.append(current_loop)
            current_loop = collections.defaultdict(list)
        elif parts[0] == 'REF' and len(parts) >= 3 and parts[1] == 'EI':
            current_loop['entity'].append(parts[2])
        else:
            for prefix in field_prefixes:
                prefix_parts = prefix.split('*')
                if parts[:len(prefix_parts)] == prefix_parts:
                    if len(parts) > len(prefix_parts):
                        current_loop[prefix].append(parts[len(prefix_parts)])

    if current_loop:
        loops.append(current_loop)

    for loop in loops:
        if 'entity' in loop and len(loop['entity']) == 1:
            ent = loop['entity'][0]
            for prefix in field_prefixes:
                if prefix in loop:
                    for val in loop[prefix]:
                        if len(val) == 8 and val.isdigit():
                            val = f"{val[:4]}-{val[4:6]}-{val[6:]}"
                        results[prefix][ent].add(val)

    return results

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    rules = {
        "wf.reverify_window": {
            "authorization expiry": [
                ("work_authorizations", "DTP*036*D8"),
                ("ead_cards", "DTP*438*D8")
            ],
            "reverification date": [
                ("reverifications", "DTP*572*D8")
            ]
        },
        "wf.notice_posting": {
            "notice posted": [
                ("lca_notices", "DTP*196*D8")
            ],
            "notice removed": [
                ("lca_notices", "DTP*197*D8")
            ],
            "LCA filed": [
                ("lca_filings", "DTP*640*D8"),
                ("dol_receipts", "DTP*009*D8")
            ]
        }
    }

    file_prefixes = collections.defaultdict(list)
    for rule, facts in rules.items():
        for fact, sources in facts.items():
            for doc, prefix in sources:
                if prefix not in file_prefixes[doc]:
                    file_prefixes[doc].append(prefix)

    extracted_data = {}
    for doc, prefixes in file_prefixes.items():
        filepath = os.path.join(dir_path, doc + ".edi")
        extracted_data[doc] = extract_facts_from_file(filepath, prefixes)

    all_entities = set()
    for filename in os.listdir(dir_path):
        if filename.endswith(".edi"):
            filepath = os.path.join(dir_path, filename)
            try:
                with open(filepath, 'r') as f:
                    content = f.read()
                segments = content.split('~')
                for segment in segments:
                    parts = segment.strip().split('*')
                    if parts[0] == 'REF' and len(parts) >= 3 and parts[1] == 'EI':
                        all_entities.add(parts[2])
            except Exception:
                pass

    all_entities = sorted(list(all_entities))

    output = {}
    for rule_name in ["wf.reverify_window", "wf.notice_posting"]:
        for entity in all_entities:
            pair = f"{rule_name}::{entity}"
            output[pair] = {}

            for fact, sources in rules[rule_name].items():
                fact_val = "ABSENT"
                for doc, prefix in sources:
                    doc_data = extracted_data.get(doc, {})
                    prefix_data = doc_data.get(prefix, {})
                    values = prefix_data.get(entity, set())

                    if len(values) == 1:
                        fact_val = [list(values)[0], doc]
                        break
                    elif len(values) > 1:
                        fact_val = "CONFLICT"
                        break
                output[pair][fact] = fact_val

    print(json.dumps(output, indent=2))

