import os
import sys
import json
import re
import datetime

def parse_first_date(text):
    m = re.search(r'\b(\d{1,2})(?:st|nd|rd|th)?\s+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{4})\b', text, re.IGNORECASE)
    m2 = re.search(r'\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,)?\s+(\d{4})\b', text, re.IGNORECASE)

    match = None
    if m and m2:
        match = m if m.start() < m2.start() else m2
    elif m:
        match = m
    elif m2:
        match = m2

    if not match:
        return None

    if match == m:
        day, month_str, year = match.groups()
    else:
        month_str, day, year = match.groups()

    month_str = month_str.lower()[:3]
    months = {'jan':1, 'feb':2, 'mar':3, 'apr':4, 'may':5, 'jun':6, 'jul':7, 'aug':8, 'sep':9, 'oct':10, 'nov':11, 'dec':12}
    return f"{year}-{months[month_str]:02d}-{int(day):02d}"

def extract_date_after_phrase(text, phrases):
    for phrase in phrases:
        idx = text.find(phrase)
        if idx != -1:
            date_str = parse_first_date(text[idx + len(phrase):])
            if date_str:
                return date_str
    return None

def add_days(date_str, days):
    d = datetime.datetime.strptime(date_str, "%Y-%m-%d")
    d += datetime.timedelta(days=days)
    return d.strftime("%Y-%m-%d")

def process_work_authorizations(body):
    if "We have no end-of-validity for that evidence." in body:
        return {'authorization expiry': "ABSENT"}
    date = extract_date_after_phrase(body, ["It is good only up to", "That evidence stops being valid on"])
    return {'authorization expiry': date}

def process_ead_cards(body):
    date = extract_date_after_phrase(body, ["Card says it runs to", "Their EAD card is printed with an end date of"])
    return {'authorization expiry': date}

def process_reverifications(body):
    if "There is no sign-off day for the Supplement B." in body:
        return {'reverification date': "ABSENT"}
    date = extract_date_after_phrase(body, ["We finished the re-verification on", "Supplement B was signed off on"])
    return {'reverification date': date}

def process_lca_notices(body):
    posted = None
    removed = None

    if "I can't tell you when the notice went up." in body:
        posted = "ABSENT"
    else:
        posted = extract_date_after_phrase(body, ["The notice went up on the board on", "We pinned the notice up on"])

    m_days = re.search(r'and came down (\d+) days later', body)
    if m_days and posted and posted != "ABSENT":
        days = int(m_days.group(1))
        removed = add_days(posted, days)
    else:
        removed = extract_date_after_phrase(body, ["We pulled the notice down on", "It was taken off the board on"])

    return {'notice posted': posted, 'notice removed': removed}

def process_lca_filings(body):
    if "I don't have a FLAG submission day." in body:
        return {'LCA filed': "ABSENT"}
    date = extract_date_after_phrase(body, ["The LCA was submitted through FLAG on", "We pushed the LCA into FLAG on"])
    return {'LCA filed': date}

def process_dol_receipts(body):
    if "No acknowledgment date from DOL is on hand." in body:
        return {'LCA filed': "ABSENT"}
    date = extract_date_after_phrase(body, ["DOL's acknowledgment is dated", "The agency acknowledged it on"])
    return {'LCA filed': date}

def process_file(filepath, process_func):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    messages = content.split('========================================================================')
    results = {}
    for msg in messages:
        msg = msg.strip()
        if not msg:
            continue
        if 'Subject:' not in msg:
            continue

        m_emp = re.search(r'Subject:.*?(E-\d{5})', msg)
        if not m_emp:
            continue
        emp_id = m_emp.group(1)

        parts = re.split(r'\n\s*\n', msg, maxsplit=1)
        body = parts[1].replace('\n', ' ') if len(parts) == 2 else msg.replace('\n', ' ')

        extracted = process_func(body)
        if emp_id not in results:
            results[emp_id] = {}
        for k, v in extracted.items():
            if v is not None:
                if k not in results[emp_id]:
                    results[emp_id][k] = set()
                results[emp_id][k].add(v)
    return results

def get_fact_value(emp_id, fact_name, primary_doc, fallback_doc, all_data):
    def get_from_doc(doc):
        if doc not in all_data:
            return None
        if emp_id not in all_data[doc]:
            return None
        if fact_name not in all_data[doc][emp_id]:
            return None

        vals = all_data[doc][emp_id][fact_name]
        if len(vals) == 0:
            return None
        elif len(vals) > 1:
            return "CONFLICT"
        else:
            return list(vals)[0]

    val = get_from_doc(primary_doc)
    if val is not None and val != "ABSENT":
        if val == "CONFLICT":
            return "CONFLICT"
        return [val, primary_doc + ".txt"]

    if fallback_doc:
        val_fallback = get_from_doc(fallback_doc)
        if val_fallback is not None and val_fallback != "ABSENT":
            if val_fallback == "CONFLICT":
                return "CONFLICT"
            return [val_fallback, fallback_doc + ".txt"]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    data_dir = sys.argv[1]

    files_to_process = {
        'work_authorizations': process_work_authorizations,
        'ead_cards': process_ead_cards,
        'reverifications': process_reverifications,
        'lca_notices': process_lca_notices,
        'lca_filings': process_lca_filings,
        'dol_receipts': process_dol_receipts
    }

    all_data = {}
    for doc_name, func in files_to_process.items():
        filepath = os.path.join(data_dir, doc_name + '.txt')
        if os.path.exists(filepath):
            all_data[doc_name] = process_file(filepath, func)
        else:
            all_data[doc_name] = {}

    pairs = [
        "wf.reverify_window::E-40401", "wf.reverify_window::E-40402", "wf.reverify_window::E-40403",
        "wf.reverify_window::E-40404", "wf.reverify_window::E-40405", "wf.reverify_window::E-40406",
        "wf.reverify_window::E-40407", "wf.reverify_window::E-40408", "wf.reverify_window::E-40409",
        "wf.reverify_window::E-40410", "wf.reverify_window::E-40411", "wf.reverify_window::E-40412",
        "wf.reverify_window::E-40413", "wf.reverify_window::E-40414", "wf.reverify_window::E-40415",
        "wf.reverify_window::E-40416",
        "wf.notice_posting::E-40401", "wf.notice_posting::E-40402", "wf.notice_posting::E-40403",
        "wf.notice_posting::E-40404", "wf.notice_posting::E-40405", "wf.notice_posting::E-40406",
        "wf.notice_posting::E-40407", "wf.notice_posting::E-40408", "wf.notice_posting::E-40409",
        "wf.notice_posting::E-40410", "wf.notice_posting::E-40411", "wf.notice_posting::E-40412",
        "wf.notice_posting::E-40413", "wf.notice_posting::E-40414", "wf.notice_posting::E-40415",
        "wf.notice_posting::E-40416"
    ]

    output = {}
    for pair in pairs:
        rule, emp_id = pair.split('::')
        output[pair] = {}

        if rule == 'wf.reverify_window':
            output[pair]['authorization expiry'] = get_fact_value(emp_id, 'authorization expiry', 'work_authorizations', 'ead_cards', all_data)
            output[pair]['reverification date'] = get_fact_value(emp_id, 'reverification date', 'reverifications', None, all_data)
        elif rule == 'wf.notice_posting':
            output[pair]['notice posted'] = get_fact_value(emp_id, 'notice posted', 'lca_notices', None, all_data)
            output[pair]['notice removed'] = get_fact_value(emp_id, 'notice removed', 'lca_notices', None, all_data)
            output[pair]['LCA filed'] = get_fact_value(emp_id, 'LCA filed', 'lca_filings', 'dol_receipts', all_data)

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
