import sys
import os
import json
import re
from datetime import datetime, timedelta

DATE_PATTERN = r'(?:(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+\d{1,2}(?:st|nd|rd|th)?,\s+\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+\d{4})'

def parse_date(date_str):
    date_str = re.sub(r'(?<=\d)(st|nd|rd|th)', '', date_str)
    date_str = re.sub(r'\s+', ' ', date_str).strip()
    formats = [
        '%B %d, %Y',
        '%b %d, %Y',
        '%d %B %Y',
        '%d %b %Y'
    ]
    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    return None

def get_body(msg):
    parts = msg.split('\n\n', 1)
    if len(parts) == 2:
        return parts[1]
    return msg

def parse_mailbox(file_path):
    if not os.path.exists(file_path):
        return []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    content = content.replace('\r\n', '\n')
    messages = content.split('========================================================================')
    parsed_messages = []
    for msg in messages:
        msg = msg.strip()
        if not msg or msg.startswith('MAILBOX EXPORT'):
            continue

        m_entity = re.search(r'\bE-\d{5}\b', msg)
        if not m_entity:
            continue
        entity = m_entity.group(0)

        body = get_body(msg)
        parsed_messages.append((entity, body))

    return parsed_messages

def extract_dol_receipts(body):
    if "No acknowledgment date" in body:
        return "ABSENT"
    m = re.search(DATE_PATTERN, body)
    if m:
        return parse_date(m.group(0))
    return None

def extract_ead_cards(body):
    m = re.search(DATE_PATTERN, body)
    if m:
        return parse_date(m.group(0))
    return None

def extract_lca_filings(body):
    if "don't have a FLAG submission day" in body:
        return "ABSENT"
    m = re.search(DATE_PATTERN, body)
    if m:
        return parse_date(m.group(0))
    return None

def extract_lca_notices(body):
    posted = None
    removed = None

    m_posted = re.search(r'(?:went up on the board on|pinned the notice up on)\s+(' + DATE_PATTERN + r')', body)
    if m_posted:
        posted = parse_date(m_posted.group(1))

    if "no record of when it was pulled down" in body:
        removed = "ABSENT"
    else:
        m_removed = re.search(r'(?:pulled the notice down on|taken off the board on)\s+(' + DATE_PATTERN + r')', body)
        if m_removed:
            removed = parse_date(m_removed.group(1))
        else:
            m_days = re.search(r'came down (\d+) days later', body)
            if m_days and posted:
                days = int(m_days.group(1))
                posted_dt = datetime.strptime(posted, '%Y-%m-%d')
                removed_dt = posted_dt + timedelta(days=days)
                removed = removed_dt.strftime('%Y-%m-%d')

    return posted, removed

def extract_reverifications(body):
    if "no sign-off day" in body:
        return "ABSENT"
    m = re.search(DATE_PATTERN, body)
    if m:
        return parse_date(m.group(0))
    return None

def extract_work_authorizations(body):
    if "no end-of-validity" in body:
        return "ABSENT"
    m = re.search(DATE_PATTERN, body)
    if m:
        return parse_date(m.group(0))
    return None

def process_simple_doc(file_path, extract_func):
    data = {}
    messages = parse_mailbox(file_path)
    for entity, body in messages:
        val = extract_func(body)
        if val is None:
            continue
        if entity not in data:
            data[entity] = val
        else:
            if data[entity] != val:
                data[entity] = "CONFLICT"
    return data

def process_lca_notices_doc(file_path):
    posted_data = {}
    removed_data = {}
    messages = parse_mailbox(file_path)
    for entity, body in messages:
        posted, removed = extract_lca_notices(body)

        if posted is not None:
            if entity not in posted_data:
                posted_data[entity] = posted
            elif posted_data[entity] != posted:
                posted_data[entity] = "CONFLICT"

        if removed is not None:
            if entity not in removed_data:
                removed_data[entity] = removed
            elif removed_data[entity] != removed:
                removed_data[entity] = "CONFLICT"

    return posted_data, removed_data

def get_fact(entity, primary_data, primary_doc, fallback_data=None, fallback_doc=None):
    if entity in primary_data:
        val = primary_data[entity]
        if val == "CONFLICT":
            return "CONFLICT"
        if val != "ABSENT":
            return [val, primary_doc]

    if fallback_data is not None and entity in fallback_data:
        val = fallback_data[entity]
        if val == "CONFLICT":
            return "CONFLICT"
        if val != "ABSENT":
            return [val, fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    dol_receipts = process_simple_doc(os.path.join(dir_path, 'dol_receipts.txt'), extract_dol_receipts)
    ead_cards = process_simple_doc(os.path.join(dir_path, 'ead_cards.txt'), extract_ead_cards)
    lca_filings = process_simple_doc(os.path.join(dir_path, 'lca_filings.txt'), extract_lca_filings)
    reverifications = process_simple_doc(os.path.join(dir_path, 'reverifications.txt'), extract_reverifications)
    work_authorizations = process_simple_doc(os.path.join(dir_path, 'work_authorizations.txt'), extract_work_authorizations)

    notice_posted, notice_removed = process_lca_notices_doc(os.path.join(dir_path, 'lca_notices.txt'))

    all_entities = set()
    for d in [dol_receipts, ead_cards, lca_filings, reverifications, work_authorizations, notice_posted, notice_removed]:
        all_entities.update(d.keys())

    hr_roster_path = os.path.join(dir_path, 'hr_roster.txt')
    if os.path.exists(hr_roster_path):
        messages = parse_mailbox(hr_roster_path)
        for entity, _ in messages:
            all_entities.add(entity)

    entities = sorted(list(all_entities))

    results = {}

    for entity in entities:
        pair_id_rev = f"wf.reverify_window::{entity}"
        results[pair_id_rev] = {
            "authorization expiry": get_fact(entity, work_authorizations, "work_authorizations.txt", ead_cards, "ead_cards.txt"),
            "reverification date": get_fact(entity, reverifications, "reverifications.txt")
        }

        pair_id_not = f"wf.notice_posting::{entity}"
        results[pair_id_not] = {
            "notice posted": get_fact(entity, notice_posted, "lca_notices.txt"),
            "notice removed": get_fact(entity, notice_removed, "lca_notices.txt"),
            "LCA filed": get_fact(entity, lca_filings, "lca_filings.txt", dol_receipts, "dol_receipts.txt")
        }

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()
