        "notice posted": [
            ("lca_notices", "board.pinned.wk")
        ],
        "notice removed": [
            ("lca_notices", "board.unpinned.wk")
        ],
        "LCA filed": [
            ("lca_filings", "lca.lodge.wk"),
            ("dol_receipts", "agency.stamp.wk")
        ]
    }
}

def format_value(val):
    if re.match(r'^\d{4}-W\d{2}-\d$', val):
        try:
            dt = datetime.datetime.strptime(val, "%G-W%V-%u")
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            return val
    return val

def load_document(filepath):
    data = defaultdict(lambda: defaultdict(set))
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter='\t')
        rows = list(reader)

    worker_row = None
    for row in rows:
        if not row or row[0].startswith('#'):
            continue
        if row[0] == 'worker.key':
            worker_row = row
            break

    if not worker_row:
        return data

    for row in rows:
        if not row or row[0].startswith('#') or row[0] == 'attribute' or row[0] == 'worker.key':
            continue
        attr = row[0]
        for col_idx in range(1, len(row)):
            if col_idx < len(worker_row):
                wkey = worker_row[col_idx]
                val = row[col_idx]
                if val != '~' and val.strip() != '':
                    data[wkey][attr].add(val)

    return data

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    docs_data = {}
    all_workers = set()

    # Load all .tsv files in the directory to find all workers and document data
    if os.path.isdir(dir_path):
        for filename in os.listdir(dir_path):
            if filename.endswith('.tsv'):
                doc_name = filename[:-4]
                filepath = os.path.join(dir_path, filename)
                doc_data = load_document(filepath)
                docs_data[doc_name] = doc_data
                for wkey in doc_data.keys():
                    all_workers.add(wkey)

    sorted_workers = sorted(list(all_workers))
    output = {}

    for rule_name in ["wf.reverify_window", "wf.notice_posting"]:
        for worker in sorted_workers:
            pair_id = f"{rule_name}::{worker}"
            pair_result = {}

            for fact_name, sources in RULES[rule_name].items():
                fact_val = "ABSENT"
                for doc_name, attr in sources:
                    if doc_name in docs_data:
                        doc_data = docs_data[doc_name]
                        if worker in doc_data and attr in doc_data[worker]:
                            vals = doc_data[worker][attr]
                            if len(vals) > 1:
                                fact_val = "CONFLICT"
                                break
                            elif len(vals) == 1:
                                val = list(vals)[0]
                                fact_val = [format_value(val), doc_name]
                                break
                pair_result[fact_name] = fact_val

            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
