def convert_value(val):
    # Convert ISO 8601 week date (YYYY-Www-D) to YYYY-MM-DD
    if re.match(r'^\d{4}-W\d{2}-\d$', val):
        try:
            dt = datetime.datetime.strptime(val, "%G-W%V-%u")
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            return val
    return val

def read_tsv(filepath):
    data = {}
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            if line.startswith('#'):
                continue
            parts = line.rstrip('\n').split('\t')
            if not parts or not parts[0]:
                continue
            attr = parts[0]
            values = parts[1:]
            data[attr] = values
    return data

def main():
    if len(sys.argv) < 2:
