    }

    parsed_docs = {}
    all_workers = set()

    for doc_name, filename in docs.items():
        filepath = os.path.join(dir_path, filename)
        if os.path.exists(filepath):
            data = read_tsv(filepath)
            parsed_docs[doc_name] = data
            if 'worker.key' in data:
                all_workers.update(data['worker.key'])

    rules = {
        "wf.reverify_window": {
            "authorization expiry": [
                ("work_authorizations", "eligibility.doc.lapse.wk"),
                ("ead_cards", "ead.lapse.wk")
