                        continue
                    doc_data = parsed_docs[doc_name]
                    if 'worker.key' not in doc_data or attr_name not in doc_data:
                        continue

                    workers = doc_data['worker.key']
                    values = doc_data[attr_name]

                    extracted_values = set()
                    for w, v in zip(workers, values):
                        if w == worker and v != '~':
                            extracted_values.add(v)

                    if len(extracted_values) > 1:
                        fact_val = "CONFLICT"
                        break
                    elif len(extracted_values) == 1:
                        val = extracted_values.pop()
                        fact_val = [convert_value(val), doc_name]
                        break
                pair_result[fact_name] = fact_val
            output[pair_id] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
