def parse_date(date_str):
    months = {
        "Jan.": "01", "Feb.": "02", "March": "03", "April": "04",
        "May": "05", "June": "06", "July": "07", "Aug.": "08",
        "Sept.": "09", "Oct.": "10", "Nov.": "11", "Dec.": "12"
    }
    m = re.search(r"(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)\.?,\s+([A-Z][a-z]+\.?)\s+(\d{1,2}),\s+(\d{4})", date_str)
    if m:
        month, day, year = m.groups()
        if month in months:
            return f"{year}-{months[month]}-{int(day):02d}"
    return None

def extract_data(filepath, fields_to_extract):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    data = {}
    sheets = re.findall(r'<article class="sheet".*?</article>', content, re.DOTALL)
