            row_m = re.search(r'<th>\s*' + re.escape(th_text) + r'\s*</th>\s*<td[^>]*>(.*?)</td>', sheet, re.DOTALL)
            if row_m:
                val_html = row_m.group(1).strip()
                if 'class="void"' in row_m.group(0) or 'left blank' in val_html:
