import sys
import os
import json
import re

MONTHS = {
    "Jan.": "01",
    "Feb.": "02",
    "March": "03",
    "April": "04",
    "May": "05",
    "June": "06",
    "July": "07",
    "Aug.": "08",
    "Sept.": "09",
    "Oct.": "10",
    "Nov.": "11",
    "Dec.": "12"
}

def parse_date(date_str):
    m = re.search(r",\s+([A-Z][a-z]+\.?)\s+(\d{1,2}),\s+(\d{4})", date_str)
    if m:
        month = MONTHS[m.group(1)]
        day = m.group(2).zfill(2)
        year = m.group(3)
        return f"{year}-{month}-{day}"
    return None

def parse_html(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    sheets = re.findall(r'<article class="sheet".*?</article>', content, re.DOTALL)

    data = {}

    for sheet in sheets:
        badge_match = re.search(r'<th>Staff badge</th>\s*<td>\s*<strong>(E-\d+)</strong>\s*</td>', sheet)
        if not badge_match:
            continue
        badge = badge_match.group(1)

        if badge not in data:
            data[badge] = {}

        fields = re.findall(r'<tr>\s*<th>(.*?)</th>\s*(<td.*?>.*?</td>)\s*</tr>', sheet, re.DOTALL)
        for field_name, td_content in fields:
            field_name = field_name.strip()
            if field_name == 'Staff badge':
                continue

            if 'class="void"' in td_content or 'left blank' in td_content:
                continue

            field_val = re.sub(r'<[^>]+>', '', td_content).strip()

            parsed_date = parse_date(field_val)
            if parsed_date:
                val = parsed_date
            else:
                val = field_val

            if field_name not in data[badge]:
                data[badge][field_name] = set()
            data[badge][field_name].add(val)

    return data

def get_fact(entity, docs_data, primary_doc, primary_field, fallback_doc=None, fallback_field=None):
    if primary_doc in docs_data:
        doc_data = docs_data[primary_doc]
        if entity in doc_data:
            if primary_field in doc_data[entity]:
                vals = doc_data[entity][primary_field]
                if len(vals) > 1:
                    return "CONFLICT"
                elif len(vals) == 1:
                    return [list(vals)[0], primary_doc]

    if fallback_doc and fallback_doc in docs_data:
        doc_data = docs_data[fallback_doc]
        if entity in doc_data:
            if fallback_field in doc_data[entity]:
                vals = doc_data[entity][fallback_field]
                if len(vals) > 1:
                    return "CONFLICT"
                elif len(vals) == 1:
                    return [list(vals)[0], fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]

    doc_files = {
        "work_authorizations": "work_authorizations.html",
        "ead_cards": "ead_cards.html",
        "reverifications": "reverifications.html",
        "lca_notices": "lca_notices.html",
        "lca_filings": "lca_filings.html",
        "dol_receipts": "dol_receipts.html"
    }

    docs_data = {}
    for doc_name, filename in doc_files.items():
        filepath = os.path.join(dir_path, filename)
        if os.path.exists(filepath):
            docs_data[doc_name] = parse_html(filepath)

    badges = set()
    for doc_data in docs_data.values():
        badges.update(doc_data.keys())

    badges = sorted(list(badges))

    rules = ["wf.reverify_window", "wf.notice_posting"]

    pairs = []
    for rule in rules:
        for badge in badges:
            pairs.append(f"{rule}::{badge}")

    results = {}

    for pair in pairs:
        rule, entity = pair.split("::")

        if rule == "wf.reverify_window":
            auth_exp = get_fact(entity, docs_data, "work_authorizations", "Evidence expires", "ead_cards", "EAD valid to")
            rev_date = get_fact(entity, docs_data, "reverifications", "Supplement B signed on")

            results[pair] = {
                "authorization expiry": auth_exp,
                "reverification date": rev_date
            }

        elif rule == "wf.notice_posting":
            notice_posted = get_fact(entity, docs_data, "lca_notices", "Notice first displayed")
            notice_removed = get_fact(entity, docs_data, "lca_notices", "Notice withdrawn from display")
            lca_filed = get_fact(entity, docs_data, "lca_filings", "Submitted through FLAG", "dol_receipts", "Agency receipt notice dated")

            results[pair] = {
                "notice posted": notice_posted,
                "notice removed": notice_removed,
                "LCA filed": lca_filed
            }

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()
