import sys
import os
import json
import re
from datetime import date, timedelta

def parse_values_clause(values_str):
    tuples = []
    in_string = False
    current_tuple = []
    current_val = []
    in_tuple = False

    i = 0
    while i < len(values_str):
        c = values_str[i]
        if c == "'" and (i == 0 or values_str[i-1] != '\\'):
            in_string = not in_string
            current_val.append(c)
        elif c == '(' and not in_string:
            in_tuple = True
            current_tuple = []
            current_val = []
        elif c == ')' and not in_string:
            in_tuple = False
            if current_val:
                current_tuple.append(''.join(current_val).strip())
                current_val = []
            tuples.append(current_tuple)
        elif c == ',' and not in_string:
            if in_tuple:
                current_tuple.append(''.join(current_val).strip())
                current_val = []
        else:
            if in_tuple:
                current_val.append(c)
        i += 1

    parsed_tuples = []
    for t in tuples:
        parsed_t = []
        for v in t:
            if v.startswith("'") and v.endswith("'"):
                parsed_t.append(v[1:-1])
            elif v.upper() == 'NULL':
                parsed_t.append(None)
            else:
                try:
                    parsed_t.append(int(v))
                except ValueError:
                    try:
                        parsed_t.append(float(v))
                    except ValueError:
                        parsed_t.append(v)
        parsed_tuples.append(parsed_t)
    return parsed_tuples

def parse_sql_inserts(filepath):
    records = []
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    insert_pattern = re.compile(r'INSERT\s+INTO\s+\w+\s*\(([^)]+)\)\s*VALUES\s*(.*?);', re.IGNORECASE | re.DOTALL)
    for match in insert_pattern.finditer(content):
        cols = [c.strip() for c in match.group(1).split(',')]
        values_str = match.group(2)

        tuples = parse_values_clause(values_str)
        for t in tuples:
            records.append(dict(zip(cols, t)))
    return records

def epd_to_date(epd):
    if epd is None:
        return None
    return (date(1970, 1, 1) + timedelta(days=int(epd))).strftime('%Y-%m-%d')

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    data_dir = sys.argv[1]

    doc_files = {
        "dol_receipts": "dol_receipts.sql",
        "ead_cards": "ead_cards.sql",
        "hr_roster": "hr_roster.sql",
        "lca_filings": "lca_filings.sql",
        "lca_notices": "lca_notices.sql",
        "reverifications": "reverifications.sql",
        "work_authorizations": "work_authorizations.sql"
    }

    data_by_doc = {}
    for doc_name, filename in doc_files.items():
        filepath = os.path.join(data_dir, filename)
        if os.path.exists(filepath):
            data_by_doc[doc_name] = parse_sql_inserts(filepath)
        else:
            data_by_doc[doc_name] = []

    rules = {
        "wf.reverify_window": {
            "authorization expiry": [
                ("work_authorizations", "eligibility_doc_lapse_epd"),
                ("ead_cards", "ead_lapse_epd")
            ],
            "reverification date": [
                ("reverifications", "i9_redo_done_epd")
            ]
        },
        "wf.notice_posting": {
            "notice posted": [
                ("lca_notices", "board_pinned_epd")
            ],
            "notice removed": [
                ("lca_notices", "board_unpinned_epd")
            ],
            "LCA filed": [
                ("lca_filings", "lca_lodge_epd"),
                ("dol_receipts", "agency_stamp_epd")
            ]
        }
    }

    entities = set()
