import sys
import os
import json
import re
from datetime import date, timedelta

def epd_to_date(epd):
    if epd is None:
        return None
    return (date(1970, 1, 1) + timedelta(days=int(epd))).strftime('%Y-%m-%d')

def parse_tuple(t_str):
    vals = []
    in_str = False
    curr_val = []
    for char in t_str:
        if char == "'":
            in_str = not in_str
        elif char == ',' and not in_str:
            vals.append(''.join(curr_val).strip())
            curr_val = []
            continue
        curr_val.append(char)
    vals.append(''.join(curr_val).strip())

    parsed = []
    for v in vals:
        if v.upper() == 'NULL':
            parsed.append(None)
        elif v.startswith("'") and v.endswith("'"):
            parsed.append(v[1:-1])
        else:
            parsed.append(v)
    return parsed

def parse_sql_inserts(sql_text):
    rows = []
    statements = re.split(r';\s*', sql_text)
    for stmt in statements:
        stmt = stmt.strip()
        if stmt.upper().startswith('INSERT INTO'):
            cols_match = re.search(r'\(([^)]+)\)', stmt)
            if not cols_match: continue
            cols = [c.strip() for c in cols_match.group(1).split(',')]

            values_match = re.search(r'\bVALUES\b', stmt, re.IGNORECASE)
            if not values_match: continue
            values_part = stmt[values_match.end():]

            tuples = []
            in_str = False
            in_tuple = False
            curr_tuple = []
            for char in values_part:
                if char == "'":
                    in_str = not in_str
                    curr_tuple.append(char)
                elif char == '(' and not in_str:
                    in_tuple = True
                elif char == ')' and not in_str:
                    in_tuple = False
                    tuples.append(''.join(curr_tuple))
                    curr_tuple = []
                elif in_tuple:
                    curr_tuple.append(char)

            for t in tuples:
                vals = parse_tuple(t)
                row = dict(zip(cols, vals))
                rows.append(row)
    return rows

def format_value(col_name, val):
    if val is None:
        return None
    if col_name.endswith('_epd'):
        return epd_to_date(val)
    return str(val)

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    db = {}
    for fname in os.listdir(dir_path):
        if fname.endswith('.sql'):
            fpath = os.path.join(dir_path, fname)
            with open(fpath, 'r', encoding='utf-8') as f:
                db[fname] = parse_sql_inserts(f.read())

    rules = {
        "wf.reverify_window": {
            "authorization expiry": [
                ("work_authorizations.sql", "eligibility_doc_lapse_epd"),
                ("ead_cards.sql", "ead_lapse_epd")
            ],
            "reverification date": [
                ("reverifications.sql", "i9_redo_done_epd")
            ]
        },
        "wf.notice_posting": {
            "notice posted": [
                ("lca_notices.sql", "board_pinned_epd")
            ],
            "notice removed": [
                ("lca_notices.sql", "board_unpinned_epd")
            ],
            "LCA filed": [
                ("lca_filings.sql", "lca_lodge_epd"),
                ("dol_receipts.sql", "agency_stamp_epd")
            ]
        }
    }

    wkr_codes = set()
    for rows in db.values():
        for row in rows:
            if 'wkr_code' in row:
                wkr_codes.add(row['wkr_code'])
    wkr_codes = sorted(list(wkr_codes))

    expected_pairs = []
    for rule in ["wf.reverify_window", "wf.notice_posting"]:
        for wkr in wkr_codes:
            expected_pairs.append(f"{rule}::{wkr}")

    results = {}
    for pair in expected_pairs:
        rule_name, wkr_code = pair.split('::')
        if rule_name not in rules:
            continue

        pair_result = {}
        for fact_name, fact_sources in rules[rule_name].items():
            fact_val = "ABSENT"
            for doc_name, col_name in fact_sources:
                if doc_name not in db:
                    continue

                records = [row for row in db[doc_name] if row.get('wkr_code') == wkr_code]
                values = set()
                for row in records:
                    val = row.get(col_name)
                    if val is not None:
                        values.add(val)

                if len(values) == 1:
                    val = values.pop()
                    formatted_val = format_value(col_name, val)
                    fact_val = [formatted_val, doc_name]
                    break
                elif len(values) > 1:
                    fact_val = "CONFLICT"
                    break

            pair_result[fact_name] = fact_val

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()
