import os
import sys
import re
import json
from datetime import datetime, timedelta

def parse_date_str(s):
    # Remove ordinal suffixes
    s = re.sub(r'(?<=\d)(st|nd|rd|th)', '', s, flags=re.IGNORECASE)
    # Remove commas
    s = s.replace(',', '')
    # Normalize spaces
    s = re.sub(r'\s+', ' ', s).strip()

    formats = [
        '%d %b %Y',
        '%d %B %Y',
        '%B %d %Y',
        '%b %d %Y'
    ]
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    return None

# Regex pattern to match dates like "17th Mar 2026", "March 22nd, 2026", etc.
date_pattern = r'(?:(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+\d{1,2}(?:st|nd|rd|th)?(?:,\s*)?\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+\d{4})'

def extract_dates(text):
    matches = re.findall(date_pattern, text, re.IGNORECASE)
    return [parse_date_str(m) for m in matches if parse_date_str(m)]

def main():
    if len(sys.argv) < 2:
        return
    target_dir = sys.argv[1]

    data = {
        'dol_receipts': {},
        'ead_cards': {},
        'hr_roster': {},
        'lca_filings': {},
        'lca_notices': {},
        'reverifications': {},
        'work_authorizations': {}
    }

    # Parse all files
    for doc_name in data.keys():
        filepath = os.path.join(target_dir, f"{doc_name}.txt")
        if not os.path.exists(filepath):
            continue

        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()

        messages = content.split('========================================================================')
        for msg in messages:
            msg = msg.strip()
            if not msg or msg.startswith('MAILBOX EXPORT'):
                continue

            m_subj = re.search(r'^Subject:\s+.*?(E-\d{5})', msg, re.MULTILINE)
            if not m_subj:
                continue
            entity_id = m_subj.group(1)

            parts = msg.split('\n\n', 1)
            if len(parts) < 2:
                continue
            body = parts[1]

            if doc_name == 'lca_notices':
                if entity_id not in data[doc_name]:
                    data[doc_name][entity_id] = {'posted': set(), 'removed': set()}

                m_posted = re.search(r'(?:went up on the board on|pinned the notice up on)\s+(' + date_pattern + r')', body, re.IGNORECASE)
                posted = None
                if m_posted:
                    posted = parse_date_str(m_posted.group(1))
                    if posted:
                        data[doc_name][entity_id]['posted'].add(posted)

                m_removed = re.search(r'(?:taken off the board on|pulled the notice down on)\s+(' + date_pattern + r')', body, re.IGNORECASE)
                if m_removed:
                    removed = parse_date_str(m_removed.group(1))
                    if removed:
                        data[doc_name][entity_id]['removed'].add(removed)
                else:
                    m_days = re.search(r'came down (\d+) days later', body, re.IGNORECASE)
                    if m_days and posted:
                        days = int(m_days.group(1))
                        posted_dt = datetime.strptime(posted, '%Y-%m-%d')
                        removed_dt = posted_dt + timedelta(days=days)
                        removed = removed_dt.strftime('%Y-%m-%d')
                        data[doc_name][entity_id]['removed'].add(removed)
            else:
                if entity_id not in data[doc_name]:
                    data[doc_name][entity_id] = set()
                dates = extract_dates(body)
                if dates:
                    data[doc_name][entity_id].add(dates[0])

    def get_fact_value(entity_id, doc_name, sub_key=None):
        if doc_name not in data or entity_id not in data[doc_name]:
            return "ABSENT", None

        if sub_key:
            vals = data[doc_name][entity_id][sub_key]
        else:
            vals = data[doc_name][entity_id]

        if len(vals) == 0:
            return "ABSENT", None
        elif len(vals) == 1:
            return list(vals)[0], doc_name
        else:
            return "CONFLICT", doc_name

    def resolve_fact(entity_id, fact_config):
        primary_doc = fact_config['primary']
        sub_key = fact_config.get('sub_key')
        fallback_doc = fact_config.get('fallback')

        val, doc = get_fact_value(entity_id, primary_doc, sub_key)

        if val == "CONFLICT":
            return "CONFLICT"
        elif val != "ABSENT":
            return [val, doc]

        if fallback_doc:
            val_fb, doc_fb = get_fact_value(entity_id, fallback_doc)
            if val_fb == "CONFLICT":
                return "CONFLICT"
            elif val_fb != "ABSENT":
                return [val_fb, doc_fb]

        return "ABSENT"

    rules = {
        'wf.reverify_window': {
            'authorization expiry': {
                'primary': 'work_authorizations',
                'fallback': 'ead_cards'
            },
            'reverification date': {
                'primary': 'reverifications',
                'fallback': None
            }
        },
        'wf.notice_posting': {
            'notice posted': {
                'primary': 'lca_notices',
                'sub_key': 'posted',
                'fallback': None
            },
            'notice removed': {
                'primary': 'lca_notices',
                'sub_key': 'removed',
                'fallback': None
            },
            'LCA filed': {
                'primary': 'lca_filings',
                'fallback': 'dol_receipts'
            }
        }
    }

    # Collect all unique entities found across all documents
    all_entities = set()
    for doc_data in data.values():
        all_entities.update(doc_data.keys())
    all_entities = sorted(list(all_entities))

    output = {}
    for rule_name, fact_configs in rules.items():
        for entity in all_entities:
            pair_id = f"{rule_name}::{entity}"
            output[pair_id] = {}
            for fact_name, config in fact_configs.items():
                output[pair_id][fact_name] = resolve_fact(entity, config)

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
